      { label: "Wikipedia: Shōjo manga", url: "https://en.wikipedia.org/wiki/Shōjo_manga" },
      { label: "Wikipedia: Isekai", url: "https://en.wikipedia.org/wiki/Isekai" },
      { label: "Wikipedia: Iyashikei", url: "https://en.wikipedia.org/wiki/Iyashikei" }
